  // ---------- plain shapes ----------
  function shape(d, c, e) { return svg('<path d="' + d + '" fill="' + c + '" stroke="' + e + '" stroke-width="4" stroke-linejoin="round"/>'); }
  add({
    circle: svg('<circle cx="50" cy="50" r="38" fill="#ff8fa3" stroke="#c2415f" stroke-width="4"/>'),
    square: shape('M16 16h68v68H16z', '#6cb8ee', '#1f5f9a'),
    triangle: shape('M50 12l40 72H10z', '#ffd95a', '#a9841c'),
    rectangle: shape('M8 28h84v44H8z', '#8fd08a', '#2f7a3a'),
    hexagon: shape('M50 8l36 21v42L50 92 14 71V29z', '#b57edc', '#5a2a6a'),
    oval: svg('<ellipse cx="50" cy="50" rx="42" ry="28" fill="#ffb347" stroke="#b9601c" stroke-width="4"/>'),
    diamond: shape('M50 8l34 42-34 42-34-42z', '#5fd0c0', '#1c6a5c'),
    arrowr: shape('M10 38h44V18l36 32-36 32V62H10z', '#3fae6a', '#1f7a44'),
    arrowl: shape('M90 38H46V18L10 50l36 32V62h44z', '#e0566b', '#8a2f45')
  });

  // a picture made of dots, for counting (n from 1 to 12)
  KQ.dots = function (n, color) {
    var cols = n <= 3 ? n : n <= 4 ? 2 : n <= 9 ? 3 : 4, rows = Math.ceil(n / cols), s = '', r = Math.min(12, 34 / Math.max(cols, rows));
    for (var i = 0; i < n; i++) {
      var cx = 50 + ((i % cols) - (cols - 1) / 2) * (r * 2.600), cy = 50 + (Math.floor(i / cols) - (rows - 1) / 2) * (r * 2.600);
      s += '<circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="' + r.toFixed(1) + '" fill="' + (color || '#ff8fa3') + '" stroke="rgba(0,0,0,.25)" stroke-width="1.500"/>';
    }
    return tile('#fff8e6', s);
  };
  // a picture that repeats one small picture n times, for counting things
  KQ.many = function (key, n) {
    var cols = n <= 3 ? n : n <= 4 ? 2 : n <= 9 ? 3 : 4, rows = Math.ceil(n / cols), s = '', sz = Math.min(44, 92 / Math.max(cols, rows));
    var inner = (P[key] || '').replace(/^<svg[^>]*>/, '').replace(/<\/svg>$/, '');
    for (var i = 0; i < n; i++) {
      var x = 50 + ((i % cols) - (cols - 1) / 2) * sz - sz / 2, y = 50 + (Math.floor(i / cols) - (rows - 1) / 2) * sz - sz / 2;
      s += '<g transform="translate(' + x.toFixed(1) + ' ' + y.toFixed(1) + ') scale(' + (sz / 100).toFixed(3) + ')">' + inner + '</g>';
    }
    return svg(s);
  };
  // a clock face showing h:m
  KQ.clockPic = function (h, m) {
    var ha = ((h % 12) + m / 60) * 30 - 90, ma = m * 6 - 90, t = '';
    for (var i = 0; i < 12; i++) { var a = i * 30 * Math.PI / 180; t += '<path d="M' + (50 + Math.cos(a) * 33).toFixed(1) + ' ' + (50 + Math.sin(a) * 33).toFixed(1) + 'L' + (50 + Math.cos(a) * (i % 3 ? 37 : 39)).toFixed(1) + ' ' + (50 + Math.sin(a) * (i % 3 ? 37 : 39)).toFixed(1) + '" stroke="#3a2a5c" stroke-width="' + (i % 3 ? 2 : 4) + '" stroke-linecap="round"/>'; }
    function hand(ang, len, w, c) { var a = ang * Math.PI / 180; return '<path d="M50 50L' + (50 + Math.cos(a) * len).toFixed(1) + ' ' + (50 + Math.sin(a) * len).toFixed(1) + '" stroke="' + c + '" stroke-width="' + w + '" stroke-linecap="round"/>'; }
    return svg('<circle cx="50" cy="50" r="44" fill="#fff8e6" stroke="#3f7fd1" stroke-width="6"/>' + t + hand(ha, 20, 6, '#3a2a5c') + hand(ma, 30, 4, '#e0566b') + '<circle cx="50" cy="50" r="4" fill="#3a2a5c"/>');
  };
